package com.sobrenaturaldirector.derivation;
import java.util.UUID;
public final class PlayerDelta { private final UUID playerId; private final boolean joined,left,healthChanged,inventoryChanged,armorChanged,dimensionChanged,death,respawn,positionChanged; private final double healthBefore,healthAfter; public PlayerDelta(UUID id,boolean joined,boolean left,boolean healthChanged,boolean inventoryChanged,boolean armorChanged,boolean dimensionChanged,boolean death,boolean respawn,boolean positionChanged,double before,double after){playerId=id;this.joined=joined;this.left=left;this.healthChanged=healthChanged;this.inventoryChanged=inventoryChanged;this.armorChanged=armorChanged;this.dimensionChanged=dimensionChanged;this.death=death;this.respawn=respawn;this.positionChanged=positionChanged;healthBefore=before;healthAfter=after;} public UUID getPlayerId(){return playerId;} public boolean isJoined(){return joined;} public boolean isLeft(){return left;} public boolean isHealthChanged(){return healthChanged;} public boolean isInventoryChanged(){return inventoryChanged;} public boolean isArmorChanged(){return armorChanged;} public boolean isDimensionChanged(){return dimensionChanged;} public boolean isDeath(){return death;} public boolean isRespawn(){return respawn;} public boolean isPositionChanged(){return positionChanged;} public double getHealthBefore(){return healthBefore;} public double getHealthAfter(){return healthAfter;} }
